"OLAYLAR_ORTACAG_ORTADOGU:0838-01-01:0":{"b": ["Mu'tasim entró en Anatolia, sitió y conquistó Amorio (Amorion)", "63534eea"], "d": ["El califa Mu'tasim entró en Anatolia en 838 con un gran ejército; avanzando por Ankara, sitió y conquistó Amorio, una de las grandes ciudades de Anatolia cerca de Afyon.", "530472b7"]},
"OLAYLAR_ORTACAG_ORTADOGU:0868-09-15:0":{"b": ["Ahmad b. Tulun entró en Egipto como lugarteniente del gobernador; se sentaron las bases de los tulúnidas", "7bfc6989"], "d": ["Ahmad b. Tulun entró en Egipto como lugarteniente del gobernador; se sentaron las bases de los tulúnidas", "7bfc6989"]},
"OLAYLAR_ORTACAG_ORTADOGU:0870-01-01:0":{"b": ["El centro administrativo se trasladó al palacio del barrio recién fundado de al-Qatai (256/870).", "f6fd1a7f"], "d": ["El centro administrativo se trasladó al palacio del barrio recién fundado de al-Qatai (256/870).", "f6fd1a7f"]},
"OLAYLAR_ORTACAG_ORTADOGU:0870-08-29:0":{"b": ["La flota aglabí conquistó Malta definitivamente (28 de ramadán 256)", "71f7ca41"], "d": ["La flota al mando de Ahmad b. Umar, uno de los comandantes aglabíes de Sicilia, conquistó Malta definitivamente (28 de ramadán 256 / 29 de agosto de 870); la isla estaba bajo dominio bizantino (romano de Oriente) desde 533 y, a partir de esta fecha, el dominio musulmán se hizo permanente. En el atlas, Malta, Mdina y Gozo figuran desde este día a nombre de los aglabíes.", "a9aa1a35"]},
"OLAYLAR_ORTACAG_ORTADOGU:0884-01-01:0":{"b": ["Murió Ahmad b. Tulun, le sucedió su hijo Jumarawayh (270/884).", "cad7d779"], "d": ["Murió Ahmad b. Tulun, le sucedió su hijo Jumarawayh (270/884).", "cad7d779"]},
