"OLAYLAR_ORTACAG_ORTADOGU:1285-01-01:0":{"b": ["Kalavun tomó a los hospitalarios la fortaleza de Margat y eliminó esa fuerza cruzada; cayó el último gran bastión cruzado en las inmediaciones del Condado de Trípoli (684/1285).", "722b884f"], "d": ["Kalavun tomó a los hospitalarios la fortaleza de Margat y eliminó esa fuerza cruzada; cayó el último gran bastión cruzado en las inmediaciones del Condado de Trípoli (684/1285).", "722b884f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1287-01-01:0":{"b": ["Murió el conde Bohemundo VII; la disputa sucesoria entre su hermana Lucia y la comuna de la ciudad, apoyada por los genoveses, debilitó el condado y dio una oportunidad a Kalavun.", "e68819ba"], "d": ["Murió el conde Bohemundo VII; la disputa sucesoria entre su hermana Lucia y la comuna de la ciudad, apoyada por los genoveses, debilitó el condado y dio una oportunidad a Kalavun.", "e68819ba"]},
"OLAYLAR_ORTACAG_ORTADOGU:1289-04-26:0":{"b": ["Kalavun conquistó Trípoli de Siria; terminó el Condado de Trípoli", "2c912cc3"], "d": ["Kalavun conquistó Trípoli de Siria; terminó el Condado de Trípoli", "2c912cc3"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-01:0":{"b": ["Sidón pasó a los mamelucos (los caballeros templarios se retiraron)", "2339a488"], "d": ["Tras la conquista de Acre (690/1291), los caballeros templarios que salieron de allí se refugiaron en Sidón; la ciudad pasó a manos de los mamelucos en rayab de 690 / julio de 1291 y sus murallas fueron derribadas.", "4c9103e0"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-14:0":{"b": ["Los mamelucos tomaron Tiro; terminó el estado cruzado de la costa (Reino de Jerusalén)", "f52aa213"], "d": ["Los mamelucos tomaron Tiro; terminó el estado cruzado de la costa (Reino de Jerusalén)", "f52aa213"]},
"OLAYLAR_ORTACAG_ORTADOGU:1310-10-03:0":{"b": ["El historiador Ebü'l-Fidâ fue nombrado por el sultán mameluco nâib de Hama (8 de yumada al-ula de 710).", "8dbf5f8f"], "d": ["El historiador Ebü'l-Fidâ fue nombrado por el sultán mameluco nâib de Hama (8 de yumada al-ula de 710).", "8dbf5f8f"]},
